(()=>{
function selectSkill(skill){selectedComposerAgent='inventory-ops-agent';const toggle=document.getElementById('agent-toggle');toggle.dataset.selectedAgent='inventory-ops-agent';toggle.dataset.selectedSkill=skill;toggle.textContent='库存作业智能体 · '+skill;toggle.title=toggle.textContent}

const columns=['行','物料编码','物料描述','物料版本','来源子库','来源货位','目标子库','目标货位','库存类型','物权组织','交易数量','交易单位','交易日期','交易原因','交易参考'];let draft=null,entry=null;
function table(edit=false){return '<table><thead><tr>'+columns.map(x=>'<th>'+x+'</th>').join('')+(edit?'<th>操作</th>':'')+'</tr></thead><tbody>'+draft.rows.map((r,i)=>'<tr>'+r.map((v,c)=>'<td>'+(edit&&c?'<input '+(c===10?'type="number" min="1"':'')+' value="'+escapeHTML(v)+'" aria-label="第 '+(i+1)+' 行'+columns[c]+'" data-row="'+i+'" data-col="'+c+'">':(c===0?escapeHTML(v)+' <button type="button" class="transfer-line-trigger" data-line-detail="'+i+'" aria-label="查看第 '+(i+1)+' 行信息" title="查看详情"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M5 3h9l5 5v13H5z"/><path d="M14 3v5h5M8 12h8M8 16h6"/></svg></button>':escapeHTML(v)))+'</td>').join('')+(edit?'<td><button data-delete="'+i+'">删除</button></td>':'')+'</tr>').join('')+'</tbody></table>'}
function sync(){entry.transferDraft=draft;saveSessionRecords();const summary=document.querySelector('.transfer-summary');if(summary)summary.innerHTML='<h3>头信息</h3><div class="transfer-table"><table><tr><th>库存组织</th><th>交易类型</th><th>申请人</th><th>申请日期</th></tr><tr>'+Object.values(draft.head).map(v=>'<td>'+escapeHTML(v)+'</td>').join('')+'</tr></table></div><h3>行信息 <small>'+draft.rows.length+' 行</small></h3><div class="transfer-table">'+table()+'</div><small>左右滚动查看完整行信息</small><p>检查无误后，在业务页面确认提交。</p><div class="stock-tools"><button data-open-transfer><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M5 2.5h9l5 5V22H5z"/><path d="M14 2.5V8h5M8.5 12h7M8.5 16h5"/></svg><span>查看已填页面</span></button></div>';summary?.querySelector('[data-open-transfer]')?.addEventListener('click',openPane);bindLineDetails(summary)}
function bindLineDetails(root){root?.querySelectorAll('[data-line-detail]').forEach(button=>button.onclick=()=>{const index=Number(button.dataset.lineDetail),row=draft.rows[index],dialog=document.createElement('dialog');dialog.className='transfer-line-dialog';dialog.setAttribute('aria-label','第 '+(index+1)+' 行转库信息');dialog.innerHTML='<header><h2>行信息 · 第 '+(index+1)+' 行</h2><button type="button" aria-label="关闭行信息">×</button></header><div class="transfer-line-fields">'+columns.map((label,i)=>'<label>'+label+'<input readonly value="'+escapeHTML(row[i])+'"></label>').join('')+'</div><footer><button type="button">关闭</button></footer>';document.body.append(dialog);dialog.querySelectorAll('button').forEach(b=>b.onclick=()=>dialog.remove());dialog.addEventListener('close',()=>dialog.remove());dialog.showModal()})}
function openPane(){document.querySelectorAll('.transfer-create-pane').forEach(p=>p.remove());const pane=document.createElement('aside');pane.className='stock-business-pane transfer-create-pane';pane.innerHTML='<div class="stock-excel-resizer" role="separator" tabindex="0"></div><header><h2>创建转库单</h2><button data-full>放大</button><button data-close aria-label="关闭转库单页面">×</button></header><div class="transfer-page-body"><h3>头信息 <span class="transfer-state">'+(draft.submitted?'已提交':'已预填 · 待确认')+'</span></h3><div class="transfer-head-fields">'+Object.entries(draft.head).map(([k,v])=>'<label>'+k+' *<input value="'+escapeHTML(v)+'" data-head="'+k+'" required></label>').join('')+'</div><h3 class="transfer-line-title">行信息 <small>'+draft.rows.length+' 行</small><button data-add>＋ 新增</button></h3><div class="transfer-table">'+table(true)+'</div><small>左右滚动查看完整字段 · 可逐行修改交易信息</small><p role="status"></p></div><footer><button data-cancel>关闭页面</button><button data-draft>保存草稿</button><button data-submit '+(draft.submitted?'disabled':'')+'>提交</button></footer>';document.body.append(pane);mountStockSplit(pane);bindLineDetails(pane);pane.querySelector('[data-cancel]').onclick=()=>pane.querySelector('[data-close]').click();pane.querySelectorAll('[data-head]').forEach(x=>x.oninput=()=>{draft.head[x.dataset.head]=x.value;sync()});pane.querySelectorAll('[data-row]').forEach(x=>x.oninput=()=>{draft.rows[+x.dataset.row][+x.dataset.col]=x.value;sync()});pane.querySelectorAll('[data-delete]').forEach(x=>x.onclick=()=>{draft.rows.splice(+x.dataset.delete,1);draft.rows.forEach((r,i)=>r[0]=String(i+1));sync();openPane()});pane.querySelector('[data-add]').onclick=()=>{draft.rows.push([String(draft.rows.length+1),'','','','RM01 · 原料子库','','WIP01 · 线边子库','','普通库存','华东制造有限公司','1','块','2026-10-26','','']);sync();openPane()};pane.querySelector('[data-draft]').onclick=()=>{sync();pane.querySelector('[role=status]').textContent='✓ 草稿已保存'};pane.querySelector('[data-submit]').onclick=()=>{if(!draft.rows.length||draft.rows.some(r=>!r[1]||Number(r[10])<=0)){pane.querySelector('[role=status]').textContent='请补齐物料编码并填写大于 0 的交易数量。';return}const dialog=document.createElement('dialog');dialog.className='transfer-confirm';dialog.innerHTML='<h2>确认提交转库单？</h2><p>请确认库存组织、物料及转库数量无误。</p><footer><button data-no>取消</button><button data-yes>确认提交</button></footer>';document.body.append(dialog);dialog.querySelector('[data-no]').onclick=()=>dialog.remove();dialog.querySelector('[data-yes]').onclick=()=>{draft.submitted=true;sync();pane.querySelector('.transfer-state').textContent='已提交';pane.querySelector('[role=status]').textContent='✓ 转库单已提交（演示）';pane.querySelector('[data-submit]').disabled=true;dialog.remove()};dialog.showModal()}}
function open(text,saved){openNewConversation();document.body.classList.add('ai-session');document.body.classList.remove('conversation-entry');document.getElementById('conversation-recommendations')?.remove();selectSkill('创建转库单');entry=saved||sessionRecords.find(x=>x.id===currentSessionId);if(!entry){entry={id:'transfer-'+Date.now(),role:sessionStorage.getItem('yunxu-role'),time:Date.now(),source:'manual',title:'创建转库单：主控板 200 块，RM01 转至 WIP01。',messages:[],read:true};sessionRecords.unshift(entry)}currentSessionId=entry.id;draft=entry.transferDraft||{head:{'库存组织':'华东库存组织','交易类型':'子库转移','申请人':document.getElementById('current-person')?.textContent||'小琴','申请日期':'2026-10-26'},rows:[['1','PCB-A100','主控板','A.1','RM01 · 原料子库','A-01-01','WIP01 · 线边子库','B-01-01','普通库存','华东制造有限公司','200','块','2026-10-26','李小梅通过 WeLink 发起：车间补料。','WL-LXM-20261026-001'],['2','CON-D400','连接器','B.2','RM01 · 原料子库','A-02-03','WIP01 · 线边子库','B-01-02','普通库存','华东制造有限公司','120','个','2026-10-26','李小梅通过 WeLink 发起：车间补料。','WL-LXM-20261026-001']]};document.getElementById('messages').innerHTML='<article class="transfer-reference"><div class="stock-user">'+escapeHTML(text)+'</div><h3>✦ 库存作业智能体</h3><p>已按转库要求打开右侧创建页，并预填业务信息。你可以直接检查和修改，也可以继续在对话中调整数量。</p><div class="transfer-summary"></div></article>';sync();openPane();renderSessionHistory();promptBox.value='';promptBox.placeholder='例如：把数量改为 300 块'}
const base=sendPrompt;sendPrompt=function(){const text=promptBox.value.trim();if(/创建转库单|录入转库单/.test(text)&&/主控板|RM01/.test(text)){open(text);return}if(document.querySelector('.transfer-reference')&&/数量.*\d+/.test(text)){const n=text.match(/数量\D*(\d+)/);if(n){draft.rows[0][10]=n[1];addMessage(text,true);sync();openPane();promptBox.value='';return}}return base.apply(this,arguments)};
})();
